// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testRegression_property() public {
        c.Initialized();
        bool ok;
        try c.SetMinSum(1) { ok = true; } catch { ok = false; }
        bool collectOk;
        try c.Collect(0) { collectOk = true; } catch { collectOk = false; }
        assertTrue(!ok && collectOk);
    }
}
